B.am=s([],t.zr)
B.WY=s(["Th..Thank you, Mateo. I..I owe you my life...","The words grow distant as exhaustion pulls you back into darkness."],t.s)
B.Ok=new A.cu("Close your eyes","intro_pass_out_to_spanish_home",!0,!1)
B.YJ=s([B.Ok],t.u)
