B.O3=new A.cu("Claim bounty","claim_italy_first_bounty",!0,!0)
B.YM=s([B.O3],t.u)
B.OU=new A.ch(B.am,B.YA,"italy_first_bounty",B.hC,null,B.YM)
B.Xn=s(["Redfin will trouble these waters no more. Spend your reward wisely, captain.","Another Redfin has been sighted. Will you take the next contract?"],t.s)
B.jR=new A.wq(2,"completed")
B.Oe=new A.cu("Accept another bounty","accept_italy_first_bounty",!0,!0)
B.WV=s([B.Oe,B.fX],t.u)
B.OX=new A.ch(B.am,B.Xn,"italy_first_bounty",B.jR,null,B.WV)
B.Uh=s(["Your target is Redfin, a vicious crimson beast seen in open waters.","It is rarely sighted. Keep fighting at sea and watch for its red scales."],t.s)
B.dm=new A.wq(0,"active")
B.P4=new A.ch(B.am,B.Uh,"italy_first_bounty",B.dm,null,B.dP)
B.Oq=new A.N8(1,"minimumEspressoCoffee")
B.Os=new A.qf(B.Oq,1)
B.Z3=s([B.Os],t.zr)
B.Zf=s(["Ah, espresso on the sea. You have excellent instincts, sailor.","Keep it close. A clear mind sees reefs long before the waves do."],t.s)
B.P_=new A.ch(B.Z3,B.Zf,null,null,null,B.dP)
B.Op=new A.N8(0,"minimumGold")
B.Or=new A.qf(B.Op,100)
B.WM=s([B.Or],t.zr)
B.Za=s(["Your purse has a reassuring weight to it.","Gold buys supplies, but a captain earns the crew's trust."],t.s)
B.Pa=new A.ch(B.WM,B.Za,null,null,null,B.dP)
B.UN=s([B.OS,B.OU,B.OX,B.P4,B.P_,B.Pa],t.J)
B.OI=new A.cM("Captain Lorenzo",B.UN)
B.Xe=s(["The British officer drove his blade into you and threw you overboard.","Through fading vision, you watched the British naval ship sail away and leave you to the sea."],t.s)
B.Oh=new A.cu("Wake up","intro_return_to_stranger",!0,!1)
B.Zi=s([B.Oh],t.u)
B.Pj=new A.ch(B.am,B.Xe,null,null,null,B.Zi)
B.W5=s([B.Pj],t.J)
B.OJ=new A.cM("Narrator",B.W5)
B.WR=s(["What happened to the treasure? This is not the island we saw from the water.","The golden shore twists into black rock as the welcoming lights vanish behind us.","Sirens... They lured us here. This entire island was a trap."],t.s)
B.P3=new A.ch(B.am,B.WR,null,null,null,B.dP)
B.VB=s([B.P3],t.J)
B.OK=new A.cM("Player",B.VB)
B.Yi=s(["You awake beneath clean blankets in an unfamiliar bedroom. Your wound aches beneath fresh bandages.","Unsteady but determined, you rise from the bed and find your footing. Your limbs scream in pain, but your mind screams louder.","You hear a firm knock on the door."],t.s)
B.On=new A.cu("Look at the door.","intro_mateo_enters_bedroom",!0,!1)
B.Yj=s([B.On],t.u)
B.Pc=new A.ch(B.am,B.Yi,null,null,null,B.Yj)
B.Z1=s([B.Pc],t.J)
B.OL=new A.cM("Narrator",B.Z1)
B.UZ=s(["Lightning tears across the water as the Kraken returns, charged with violent energy.","This encounter will become the Kraken's second phase."],t.s)
